            var ephemeralMessageIds: [MessageId] = []
            var normalMessages: [(Bool, EnqueueMessage)] = []
            var normalMessageIndices: [Int] = []
            let anonymousStickersEnabled = UserDefaults.standard.object(forKey: "nagramix.stickers.anonymous") as? Bool ?? true
            let antiCapsEnabled = UserDefaults.standard.object(forKey: "nagramix.messages.antiCaps") as? Bool ?? true
            let antiCapsLimits = antiCapsEnabled ? UserLimitsConfiguration(appConfiguration: transaction.getPreferencesEntry(key: PreferencesKeys.appConfiguration)?.get(AppConfiguration.self) ?? .defaultValue, isPremium: (transaction.getPeer(account.peerId) as? TelegramUser)?.isPremium ?? false) : UserLimitsConfiguration.defaultValue

