private final class AccountPresenceManagerImpl {
    private let queue: Queue
    private let network: Network
    let isPerformingUpdate = ValuePromise<Bool>(false, ignoreRepeated: true)

    private var shouldKeepOnlinePresenceDisposable: Disposable?
    private let currentRequestDisposable = MetaDisposable()
    private var onlineTimer: SignalKitTimer?

    private var wasOnline: Bool = false
    private var ghostSettings = NagramiXGhostSettings()

    init(queue: Queue, shouldKeepOnlinePresence: Signal<Bool, NoError>, network: Network) {
        self.queue = queue
        self.network = network

        self.shouldKeepOnlinePresenceDisposable = (combineLatest(shouldKeepOnlinePresence |> distinctUntilChanged, nagramiXGhostSettingsSignal())
        |> deliverOn(self.queue)).start(next: { [weak self] value, settings in
            guard let `self` = self else {
                return
            }
            let changed = self.ghostSettings.hidesOnline != settings.hidesOnline || self.ghostSettings.automaticOffline != settings.automaticOffline
            self.ghostSettings = settings
            if self.wasOnline != value || changed {
                self.wasOnline = value
                self.updatePresence(value, forceOffline: value && settings.automaticOffline)
            }
        })
    }

    deinit {
        assert(self.queue.isCurrent())
        self.shouldKeepOnlinePresenceDisposable?.dispose()
        self.currentRequestDisposable.dispose()
        self.onlineTimer?.invalidate()
    }

    private func updatePresence(_ requestedOnline: Bool, forceOffline: Bool = false) {
        let settings = NagramiXGhostSettings.current
        let directive = settings.presenceDirective(requestedOnline: requestedOnline, forceOffline: forceOffline)
        if directive == .unchanged {
            self.onlineTimer?.invalidate(); self.onlineTimer = nil
            self.currentRequestDisposable.set(nil)
            self.isPerformingUpdate.set(false)
            return
        }
        let isOnline = directive == .online
        let request: Signal<Api.Bool, MTRpcError>
        if isOnline {
            let timer = SignalKitTimer(timeout: 30.0, repeat: false, completion: { [weak self] in
                guard let strongSelf = self else {
                    return
                }
                strongSelf.updatePresence(true)
            }, queue: self.queue)
            self.onlineTimer = timer
            timer.start()
            request = self.network.request(Api.functions.account.updateStatus(offline: .boolFalse))
        } else {
            self.onlineTimer?.invalidate()
            self.onlineTimer = nil
            request = self.network.request(Api.functions.account.updateStatus(offline: .boolTrue))
            // Automatic offline is an immediate transition. The separate
            // hide-online option controls whether later keepalives stay hidden.
            if forceOffline && !settings.hidesOnline && self.wasOnline {
                let timer = SignalKitTimer(timeout: 30.0, repeat: false, completion: { [weak self] in self?.updatePresence(true) }, queue: self.queue)
                self.onlineTimer = timer
                timer.start()
            }
        }
        self.isPerformingUpdate.set(true)
        self.currentRequestDisposable.set((request
        |> `catch` { _ -> Signal<Api.Bool, NoError> in
            return .single(.boolFalse)
        }
        |> deliverOn(self.queue)).start(completed: { [weak self] in
            guard let strongSelf = self else {
                return
            }
            strongSelf.isPerformingUpdate.set(false)
        }))
    }
}
