        // Successful online-inducing actions belong to this account's Network.
        // Our own status RPC is excluded, so an offline request cannot loop.
        self.onlineActivityDisposable = (network.nagramiXOnlineActivity
        |> deliverOn(self.queue)).start(next: { [weak self] _ in
            guard let self, NagramiXGhostSettings.current.hidesOnline else { return }
            self.updatePresence(self.wasOnline)
