    private func updatePresence(_ requestedOnline: Bool) {
        let settings = NagramiXGhostSettings.current
        let directive = settings.presenceDirective(requestedOnline: requestedOnline, forceOffline: true)
        self.refreshGeneration &+= 1
        self.onlineTimer?.invalidate()
