        // Retain Telegram's refresh interval; hidden mode only refreshes OFFLINE.
        if requestedOnline && self.wasOnline {
            let generation = self.refreshGeneration
            let timer = SignalKitTimer(timeout: 30.0, repeat: false, completion: { [weak self] in
                guard let self, self.wasOnline, self.refreshGeneration == generation else { return }
                self.updatePresence(true)
