            self.onlineTimer = timer
            timer.start()
        }

        let isOnline = directive == .online
        if !isOnline && self.offlineRequestInFlight {
            // Never cancel an unacknowledged offline RPC during a busy burst.
            // One trailing request covers actions processed after it by the server.
            self.repeatOfflineAfterCompletion = true
            return
        }
        self.requestGeneration &+= 1
        let generation = self.requestGeneration
        self.offlineRequestInFlight = !isOnline
        self.repeatOfflineAfterCompletion = false
        self.isPerformingUpdate.set(true)
        let request = self.network.request(Api.functions.account.updateStatus(offline: isOnline ? .boolFalse : .boolTrue))
        self.currentRequestDisposable.set((request
        |> `catch` { _ -> Signal<Api.Bool, NoError> in
            return .single(.boolFalse)
        }
        |> deliverOn(self.queue)).start(completed: { [weak self] in
            guard let self, self.requestGeneration == generation else { return }
            self.offlineRequestInFlight = false
            let repeatOffline = self.repeatOfflineAfterCompletion && NagramiXGhostSettings.current.hidesOnline
            self.repeatOfflineAfterCompletion = false
            if repeatOffline {
                self.queue.async { [weak self] in
                    guard let self, self.requestGeneration == generation,
                          NagramiXGhostSettings.current.hidesOnline else { return }
                    self.updatePresence(self.wasOnline)
                }
            } else {
                self.isPerformingUpdate.set(false)
            }
        }))
