    private static func nagramiXRPCMayRestoreOnline(_ name: String) -> Bool {
        // Telegram may expose online temporarily after reads, sends and typing.
        // Exclude status refreshes (especially our own offline request), queries,
        // uploads/downloads and keepalives to avoid a self-sustaining timer loop.
        if name.hasPrefix("messages.send") || name.hasPrefix("messages.read") || name.hasPrefix("channels.read") { return true }
        switch name {
        case "messages.forwardMessages", "messages.editMessage", "messages.editInlineBotMessage", "messages.startBot",
             "messages.setTyping", "messages.setEncryptedTyping", "messages.getMessagesViews",
             "stories.readStories", "stories.incrementStoryViews", "stories.sendReaction", "stories.sendStory",
             "phone.requestCall", "phone.acceptCall", "phone.confirmCall", "phone.joinGroupCall":
            return true
        default:
            return false
        }
